con:config.script:
    log.info "Start disabling targeted test cases ..."

	def targeted_TC_List = ["Dom00125-Push-EDELIVERY-1731-Manual- CXF attachment temporary files leakage", "Dom00135-Push-Manual- BIG attachments",
							"Dom00155-EDELIVERY-2857-Weblogic Cluster", "Dom00425-Pull-EDELIVERY-1731-Manual- CXF attachment temporary files leakage",
							"Dom00490-EDELIVERY-4830-Downloading the CRL via HTTPs is not working", "Dom00496-UI-Replication",
							"Dom00527-Payload size"]


	targeted_TC_List.each { tcName ->
		def tcList = testRunner.testCase.testSuite.testCaseList.findAll {it.label =~ /${tcName}/ }
		if (tcList.size() == 0) 	log.warn "Incorrect name of test case for disabling: \"${tcName}\""
		else {
			tcList.each { tc ->
				if (!tc.isDisabled()) {
					log.info "---- Disabling test case: \"${tc.name}\" "
					tc.setDisabled(true)
				} else {
					log.warn "---- The test case \"${tc.name}\" is already disabled ..."
				}

			}
		}
	}

	log.info "DONE."

    log.info "Start Enabling targeted test cases ..."

	def targeted_TC_List = ["Dom00125-Push-EDELIVERY-1731-Manual- CXF attachment temporary files leakage", "Dom00135-Push-Manual- BIG attachments",
							"Dom00155-EDELIVERY-2857-Weblogic Cluster", "Dom00425-Pull-EDELIVERY-1731-Manual- CXF attachment temporary files leakage",
							"Dom00490-EDELIVERY-4830-Downloading the CRL via HTTPs is not working", "Dom00496-UI-Replication",
							"Dom00527-Payload size"]


	targeted_TC_List.each { tcName ->
		def tcList = testRunner.testCase.testSuite.testCaseList.findAll {it.label =~ /${tcName}/ }
		if (tcList.size() == 0) 	log.warn "Incorrect name of test case for disabling: \"${tcName}\""
		else {
			tcList.each { tc ->
				if (tc.isDisabled()) {
					log.info "---- Enabling test case: \"${tc.name}\" "
					tc.setDisabled(false)
				} else {
					log.warn "---- The test case \"${tc.name}\" is already enabled ..."
				}

			}
		}
	}

	log.info "DONE."

