con:config.script:
def usersList = ['KeystoreCertImminentBeforeFirstDay', 'KeystoreCertImminentFirstDay' , 'KeystoreCertImminenLastDay',
				'TruststoreCertImminentBeforeFirstDay', 'TruststoreCertImminentFirstDay', 'TruststoreCertImminenLastDay']

def tc = testRunner.testCase
def dateString = new Date().format("MMddHHmmss")

for (u in usersList) {
	tc.setPropertyValue(u, tc.getPropertyValue(u).replaceFirst(/\d*$/, dateString))
}

//Create iminent certificate
def tcIdPrefix =context.expand('${#TestCase#tcIdPrefix}' )
def KeystoreCertImminentBeforeFirstDay  =  context.expand('${#TestCase#KeystoreCertImminentBeforeFirstDay}' )
def KeystoreCertImminentFirstDay  =  context.expand('${#TestCase#KeystoreCertImminentFirstDay}' )
def KeystoreCertImminenLastDay  =  context.expand('${#TestCase#KeystoreCertImminenLastDay}' )

def TruststoreCertImminentBeforeFirstDay  =  context.expand('${#TestCase#TruststoreCertImminentBeforeFirstDay}' )
def TruststoreCertImminentFirstDay  =  context.expand('${#TestCase#TruststoreCertImminentFirstDay}' )
def TruststoreCertImminenLastDay  =  context.expand('${#TestCase#TruststoreCertImminenLastDay}' )

def defPass = context.expand('${#TestCase#keystoreDefaultPassword}')
def alertCertImminentExpirationDelayDays =  context.expand('${#TestCase#defaultAlertCertImminentExpirationDelayDays}') as Integer

def workingDirectory = context.expand('${#Project#tempFilesDir}')
def blueKeystoreFileName = tcIdPrefix + "_blue_gateway_keystore.jks"
def blueKeystoreFileName2 = tcIdPrefix + "_blue_gateway_keystore_2nd.jks"
def blueTruststoreFileName = tcIdPrefix + "_blue_gateway_truststore.jks"

Domibus.deleteFiles(log, workingDirectory, tcIdPrefix +"_blue_gateway")

TruststoreUtils.generateKeyStore(context, log, workingDirectory, "blue_gw",defPass , defPass, 200, blueKeystoreFileName) // not neede in general
TruststoreUtils.generateKeyStore(context, log, workingDirectory, KeystoreCertImminentBeforeFirstDay,defPass , defPass, alertCertImminentExpirationDelayDays + 1 , blueKeystoreFileName)
TruststoreUtils.generateKeyStore(context, log, workingDirectory, KeystoreCertImminentFirstDay,defPass , defPass, alertCertImminentExpirationDelayDays - 1, blueKeystoreFileName)
TruststoreUtils.generateKeyStore(context, log, workingDirectory, KeystoreCertImminenLastDay,defPass , defPass, 1, blueKeystoreFileName)

TruststoreUtils.generateKeyStore(context, log, workingDirectory, TruststoreCertImminentBeforeFirstDay,defPass , defPass, alertCertImminentExpirationDelayDays+1, blueKeystoreFileName2)
TruststoreUtils.generateKeyStore(context, log, workingDirectory, TruststoreCertImminentFirstDay,defPass , defPass, alertCertImminentExpirationDelayDays - 1, blueKeystoreFileName2)
TruststoreUtils.generateKeyStore(context, log, workingDirectory, TruststoreCertImminenLastDay,defPass , defPass, 1, blueKeystoreFileName2)

TruststoreUtils.updateTrustStore(context, log, workingDirectory, TruststoreCertImminentBeforeFirstDay, defPass, defPass, blueKeystoreFileName2, blueTruststoreFileName)
TruststoreUtils.updateTrustStore(context, log, workingDirectory, TruststoreCertImminentFirstDay, defPass, defPass, blueKeystoreFileName2, blueTruststoreFileName)
TruststoreUtils.updateTrustStore(context, log, workingDirectory, TruststoreCertImminenLastDay, defPass, defPass, blueKeystoreFileName2, blueTruststoreFileName)

// Copy keystore blue
def source = workingDirectory + "\\" + blueKeystoreFileName
def dest = context.expand('${#Project#pathBlue}') +"conf\\domibus\\keystores\\" + blueKeystoreFileName
Domibus.copyFile(source, dest, log)
sleep(1000)

// Change keystore name
Domibus.changePropertyAtRuntime("C2", "domibus.security.keystore.location", "\${domibus.config.location}/keystores/" + blueKeystoreFileName, context, log)
sleep(1000)

// Upload truststores: blue for sender and red for receiver.
TruststoreUtils.uploadTruststore("sender","temp", blueTruststoreFileName, context, log)
sleep(1000)

Domibus.deleteFiles(log, workingDirectory, ".jks")

def side="Blue"
def test = new Domibus(log,null,context)

def KeystoreCertImminentBeforeFirstDay = testRunner.testCase.getPropertyValue( "KeystoreCertImminentBeforeFirstDay" )
def KeystoreCertImminentFirstDay = testRunner.testCase.getPropertyValue( "KeystoreCertImminentFirstDay" )
def KeystoreCertImminenLastDay = testRunner.testCase.getPropertyValue( "KeystoreCertImminenLastDay" )
def TruststoreCertImminentBeforeFirstDay = testRunner.testCase.getPropertyValue( "TruststoreCertImminentBeforeFirstDay" )
def TruststoreCertImminentFirstDay = testRunner.testCase.getPropertyValue( "TruststoreCertImminentFirstDay" )
def TruststoreCertImminenLastDay = testRunner.testCase.getPropertyValue( "TruststoreCertImminenLastDay" )

test.verifyCertAlerts(side, KeystoreCertImminentBeforeFirstDay, null, null, null, 0)
test.verifyCertAlerts(side, KeystoreCertImminentFirstDay, "CERT_IMMINENT_EXPIRATION", "SUCCESS", "HIGH", 1)
test.verifyCertAlerts(side, KeystoreCertImminenLastDay, "CERT_IMMINENT_EXPIRATION", "SUCCESS", "HIGH", 1)
test.verifyCertAlerts(side, TruststoreCertImminentBeforeFirstDay, null, null, null, 0)
test.verifyCertAlerts(side, TruststoreCertImminentFirstDay, "CERT_IMMINENT_EXPIRATION", "SUCCESS", "HIGH", 1)
test.verifyCertAlerts(side, TruststoreCertImminenLastDay, "CERT_IMMINENT_EXPIRATION", "SUCCESS", "HIGH", 1)

test.finalize()

// Revert property change
//Cron expression that specifies the frequency of the certificate revocation check.
//domibus.certificate.check.cron=0 0/5 0/1 * * ?
def defaultValueCertificateCron = context.expand('${#TestCase#defaultValueCertificateCron}')

Domibus.changePropertyAtRuntime("C2", "domibus.certificate.check.cron", defaultValueCertificateCron, context, log);

// Reset keystore name
Domibus.changePropertyAtRuntime("C2", "domibus.security.keystore.location", "\${domibus.config.location}/keystores/gateway_keystore.jks", context, log)

def tcIdPrefix =context.expand('${#TestCase#tcIdPrefix}' )
def blueKeystoreFileName = tcIdPrefix + "_blue_gateway_keystore.jks"
def dest = context.expand('${#Project#pathBlue}') +"conf\\domibus\\keystores\\"
Domibus.deleteFiles(log, dest, blueKeystoreFileName)

con:testCase.con:tearDownScript:
Domibus.reportTestCaseCsv(testRunner, log);

// Revert properties change
testRunner.testCase.testSteps['Revert properties change'].run(testRunner, context);

// Reset keystore name
testRunner.testCase.testSteps['Restore keystore name'].run(testRunner, context);

// Upload default truststore
testRunner.testCase.testSteps['Upload default truststores Blue'].run(testRunner, context);

