import groovy.io.FileType

 def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def projectPath = groovyUtils.projectPath
def sourceFile= projectPath+ "/resources/PModesandKeystoresSpecialTests/taxud/UumdsJson/ServiceLookUp/uumds-metadata.json"


def pathBlue = testRunner.testCase.testSuite.project.getPropertyValue("pathBlue")
def destPath = pathBlue + "/conf/domibus/extensions/config"
def destFilePath =  pathBlue + "conf/domibus/extensions/config/uumds-metadata.json"


new File(destPath).eachFile (FileType.FILES) { file ->
//Delete file if file exists
   if (file.name.contains('uumds-metadata.json')) file.delete()
}


  def sourceFfile = new File(sourceFile)
  log.info sourceFfile

  def destFfile = new File(destFilePath)
  log.info destFfile

  destFfile << sourceFfile.bytes
  log.info destFfile

