testRunner.testCase.testSuite.project.setPropertyValue(domain+".jmsClientType", jmsClientType);
testRunner.testCase.testSuite.project.setPropertyValue(domain+".jmxPort", jmxPort);
testRunner.testCase.testSuite.project.setPropertyValue(domain+".hostname", hostname);

sleep(3000)

