testRunner.testCase.testSuite.project.removeProperty(domain+".jmsClientType");
testRunner.testCase.testSuite.project.removeProperty(domain+".jmxPort");
testRunner.testCase.testSuite.project.removeProperty(domain+".hostname");

log.info "DONE"

