import org.apache.activemq.ActiveMQConnectionFactory
import org.apache.activemq.broker.jmx.QueueViewMBean
import javax.jms.*
import javax.management.MBeanServerConnection
import javax.management.MBeanServerInvocationHandler
import javax.management.ObjectName
import javax.management.remote.JMXConnector
import javax.management.remote.JMXConnectorFactory
import javax.management.remote.JMXServiceURL

def jmxHost="localhost"
def jmxPort="1199"
def queueName="domibus.internal.earchive.queue"

JMXServiceURL url = new JMXServiceURL("service:jmx:rmi:///jndi/rmi://"+jmxHost+":"+jmxPort+"/jmxrmi");
JMXConnector jmxc = JMXConnectorFactory.connect(url);
MBeanServerConnection conn = jmxc.getMBeanServerConnection();
ObjectName queue = new ObjectName("org.apache.activemq:type=Broker,brokerName=localhost,destinationType=Queue,destinationName="+queueName);

QueueViewMBean qw = MBeanServerInvocationHandler.newProxyInstance(conn, queue, QueueViewMBean.class, true);

try{
//qw.pause()
qw.resume()
//qw.purge()
}catch(Exception ex){
	log.info "exception: ",ex
}

log.info "DONE!"

def test = new Domibus(log,null,context);
