import com.eviware.soapui.support.GroovyUtils
import com.eviware.soapui.impl.wsdl.loadtest.WsdlLoadTestRunner
import com.eviware.soapui.impl.wsdl.testcase.WsdlTestCaseRunner
import com.eviware.soapui.config.LoadTestLimitTypesConfig

// Test cases
def submitMessageTestCase = testRunner.testCase.testSuite.testCases["Submit Message"]
def retrieveMessageTestCase = testRunner.testCase.testSuite.testCases["Retrieve Message"]
def listPendingTestCase = testRunner.testCase.testSuite.testCases["List Pending Messages"]

log.info "Start"
log.info "[Load] Submit messages"
def submitMessagesLoadTest = submitMessageTestCase.getLoadTestByName("LoadTest Submit Messages");
def loadTestRunner = new WsdlLoadTestRunner(submitMessagesLoadTest);
loadTestRunner.start(true);
loadTestRunner.waitUntilFinished();

log.info "[Load] Simulate some traffic submitting messages at the rate of two messages every three seconds for two minutes"
def trafficLoadTest = submitMessageTestCase.getLoadTestByName("LoadTest Submit Messages - Extra Traffic");
def trafficLoadTestRunner = new WsdlLoadTestRunner(trafficLoadTest);
trafficLoadTestRunner.start(true);

log.info "Sleep for 20 seconds"
Thread.sleep(20000);
log.info "Awake"

log.info "List pending messages"
def wsdlTestRunner = new WsdlTestCaseRunner(listPendingTestCase, null);
wsdlTestRunner.start(true);
wsdlTestRunner.waitUntilFinished();
def listPendingMessagesResponse = wsdlTestRunner.testCase.testSteps["listPendingMessages"].getPropertyValue("response");
def groovyUtils = new GroovyUtils(context)
def holder = groovyUtils.getXmlHolder("${listPendingMessagesResponse}")

def pendingMessageIdentifiers = holder.getNodeValues("//messageID");
log.info "pendingMessageIdentifiers = ${pendingMessageIdentifiers}"


log.info "[Load] Retrieve messages"
// Refresh Test Case properties
retrieveMessageTestCase.propertyNames.each { propertyName -> retrieveMessageTestCase.removeProperty(propertyName) }
pendingMessageIdentifiers.eachWithIndex { messageIdentifier, index -> retrieveMessageTestCase.setPropertyValue("messageIdentifier_${index}", messageIdentifier) }
def retrieveMessagesLoadTest = retrieveMessageTestCase.getLoadTestByName("LoadTest Retrieve Messages");
retrieveMessagesLoadTest.setLimitType(LoadTestLimitTypesConfig.COUNT);
retrieveMessagesLoadTest.setTestLimit(pendingMessageIdentifiers.length);
loadTestRunner = new WsdlLoadTestRunner(retrieveMessagesLoadTest);
loadTestRunner.start(true);
loadTestRunner.waitUntilFinished();
log.info "End"

