con:response.con:script:
import org.apache.commons.io.IOUtils

def groovyUtils = new com.eviware.soapui.support.GroovyUtils(context)
def path = groovyUtils.projectPath + "\\resources\\PModesandKeystoresSpecialTests\\certificates\\https_crl\\NATIONALITANDTELECOMAGENCYPEPPOLRootCA.crl"
def headers = mockResponse.responseHeaders
def httpResponse = mockRequest.httpResponse
def file = new File(path);

try{
	FileInputStream fis= new FileInputStream(file);
	OutputStream outputStream = httpResponse.getOutputStream()
	IOUtils.copy(fis,outputStream)
	fis.close()
	outputStream.close()
}
catch (Exception e){
	log.info "error"
}
mockRequest.httpResponse.addHeader("Content-Type", "application/octet-stream")
mockRequest.httpResponse.addHeader("Content-Disposition", "attachment;filename="+file)

